// ============================================================
// NOVA v2.1.0 — Orientadora y Gestora de Citas
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// CAMBIOS v2.1.0 (Paso 2 — Claude NLG):
//   - Motor ahora emite novaAction + claudeSkip + claudeContext
//     para que la capa NLG sepa qué personalizar y cuándo saltar
//   - pendingMessage en sage/atlas context reset (fix v2.0.6)
//   - sage Y atlas context reset al hacer handoff (fix estado huérfano)
//   - PT menu usa comandos que el router detecta (cotizar/comparar/agendar)
//   - STRINGS siguen como fallback garantizado si Claude falla
// ============================================================

const inp = $input.first().json;

const REQUIRED = ['userId', 'sessionId', 'remoteJid', 'instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing } }];
}

const ctx    = inp.sessionContext || {};
const nova   = ctx.nova || {};
const state  = nova.state || 'welcome';
const txt    = (inp.messageText || '').toLowerCase().trim();
const intent = inp.intentDetected || '';
const ph     = inp.pendingHandoff || null;
const fn     = inp.userName ? inp.userName.split(' ')[0] : null;
const nm     = fn ? ` ${fn}` : '';
const isNew  = inp.isNewSession || ['initial', 'initial_presented'].includes(inp.sessionState);
const LANG   = inp.detectedLanguage || inp.userLanguage || 'es';

// ── STRINGS — fallback garantizado ─────────────────────────
const STRINGS = {
  es: {
    welcome:           `¡Hola${nm}! 👋 Soy *NOVA*, tu asistente de *Pangi*.\n\nEstoy aquí para ayudarte a navegar los servicios de salud internacional. ¿Qué necesitas hoy?\n\n💰 Escribe *cotizar* — Recibe precios precisos de médicos\n🗺️ Escribe *comparar* — Analiza el costo total de tu viaje médico\n🗓️ Escribe *agendar* — Busca médicos y reserva citas\n\n¿Con cuál puedo ayudarte?`,
    saludo:            `¡Hola de nuevo${nm}! 👋 ¿En qué puedo ayudarte hoy?\n\n💰 *Cotizar* un procedimiento médico\n🗺️ *Comparar* destinos de turismo médico\n🗓️ *Agendar* una cita`,
    fallback:          `Entiendo${nm}. Puedo orientarte en estas áreas:\n\n💰 *Cotizar* — Precios precisos de médicos para tu procedimiento\n🗺️ *Comparar destinos* — Costo total real de tu viaje médico\n🗓️ *Agendar* — Encuentra médicos disponibles en tu ciudad\n\n¿Cuál te interesa?`,
    handoff_sage:      `Perfecto${nm}. Te conecto con *SAGE* 🩺, nuestra especialista en cotizaciones médicas.\n\n¿Sobre qué procedimiento deseas cotizar?`,
    handoff_atlas:     `Claro${nm}. Te presento a *ATLAS* 🗺️, nuestro consejero de turismo médico.\n\nAnalizará tus opciones y calculará el costo real del viaje médico incluyendo vuelo, alojamiento y recuperación. ¿Listo/a para explorar?`,
    ask_city:          `Entendido${nm}. Para encontrar médicos disponibles y agendar tu cita, necesito saber:\n\n*¿En qué ciudad necesitas la cita?*\n\nEscríbela y seguimos.`,
    city_received:     `Perfecto, *{city}* 📍\n\n¿Qué *especialidad médica* necesitas?\n\nPor ejemplo: dental, cardiología, traumatología, oftalmología...`,
    appointment_done:  `Entendido${nm} 📋\n\n*Tu búsqueda registrada:*\n📍 Ciudad: {city}\n🏥 Especialidad: {specialty}\n\n⏳ La búsqueda de médicos y agendamiento en línea estarán disponibles próximamente. Tu solicitud quedó registrada.\n\n¿En qué más puedo ayudarte?`,
  },
  en: {
    welcome:           `Hello${nm}! 👋 I'm *NOVA*, your *Pangi* assistant.\n\nI'm here to help you navigate international healthcare services. What do you need today?\n\n💰 Type *quote* — Get precise prices from doctors\n🗺️ Type *compare* — Analyze the total cost of your medical trip\n🗓️ Type *schedule* — Find doctors and book appointments\n\nWhich can I help you with?`,
    saludo:            `Welcome back${nm}! 👋 How can I help you today?\n\n💰 *Quote* a medical procedure\n🗺️ *Compare* medical tourism destinations\n🗓️ *Schedule* an appointment`,
    fallback:          `I understand${nm}. I can guide you in these areas:\n\n💰 *Quote* — Precise prices from doctors for your procedure\n🗺️ *Compare destinations* — Real total cost of your medical trip\n🗓️ *Schedule* — Find available doctors in your city\n\nWhich interests you?`,
    handoff_sage:      `Perfect${nm}. Let me connect you with *SAGE* 🩺, our medical quotes specialist.\n\nWhat procedure would you like a quote for?`,
    handoff_atlas:     `Sure${nm}. Meet *ATLAS* 🗺️, our medical tourism advisor.\n\nHe'll analyze your options and calculate the real cost of your medical trip including flight, accommodation and recovery. Ready to explore?`,
    ask_city:          `Understood${nm}. To find available doctors and schedule your appointment, I need to know:\n\n*In which city do you need the appointment?*\n\nType it and we'll continue.`,
    city_received:     `Perfect, *{city}* 📍\n\nWhat *medical specialty* do you need?\n\nFor example: dental, cardiology, traumatology, ophthalmology...`,
    appointment_done:  `Understood${nm} 📋\n\n*Your search registered:*\n📍 City: {city}\n🏥 Specialty: {specialty}\n\n⏳ Doctor search and online scheduling will be available soon on Pangi. Your request has been registered.\n\nHow else can I help you?`,
  },
  pt: {
    welcome:           `Olá${nm}! 👋 Sou *NOVA*, sua assistente da *Pangi*.\n\nEstou aqui para te ajudar a navegar pelos serviços de saúde internacional. O que você precisa hoje?\n\n💰 Escreva *cotizar* — Receba preços precisos de médicos\n🗺️ Escreva *comparar* — Analise o custo total da sua viagem médica\n🗓️ Escreva *agendar* — Encontre médicos e reserve consultas\n\nCom qual posso te ajudar?`,
    saludo:            `Bem-vindo de volta${nm}! 👋 Como posso te ajudar hoje?\n\n💰 *Cotizar* um procedimento médico\n🗺️ *Comparar* destinos de turismo médico\n🗓️ *Agendar* uma consulta`,
    fallback:          `Entendo${nm}. Posso te orientar nestas áreas:\n\n💰 *Cotizar* — Preços precisos de médicos para seu procedimento\n🗺️ *Comparar destinos* — Custo total real da sua viagem médica\n🗓️ *Agendar* — Encontre médicos disponíveis na sua cidade\n\nQual te interessa?`,
    handoff_sage:      `Perfeito${nm}. Vou te conectar com *SAGE* 🩺, nossa especialista em cotações médicas.\n\nSobre qual procedimento você deseja cotar?`,
    handoff_atlas:     `Claro${nm}. Conheça *ATLAS* 🗺️, nosso conselheiro de turismo médico.\n\nEle vai analisar suas opções e calcular o custo real da viagem médica incluindo voo, hospedagem e recuperação. Pronto/a para explorar?`,
    ask_city:          `Entendido${nm}. Para encontrar médicos disponíveis e agendar sua consulta, preciso saber:\n\n*Em qual cidade você precisa da consulta?*\n\nEscreva e continuamos.`,
    city_received:     `Perfeito, *{city}* 📍\n\nQual *especialidade médica* você precisa?\n\nPor exemplo: dental, cardiologia, traumatologia, oftalmologia...`,
    appointment_done:  `Entendido${nm} 📋\n\n*Sua busca registrada:*\n📍 Cidade: {city}\n🏥 Especialidade: {specialty}\n\n⏳ A busca por médicos disponíveis e o agendamento online estarão disponíveis em breve no Pangi. Sua solicitação foi registrada.\n\nComo mais posso te ajudar?`,
  }
};

const t = (key, vars) => {
  const L = STRINGS[LANG] || STRINGS.es;
  let str = L[key] || STRINGS.es[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars))
    str = str.split(`{${k}}`).join(v != null ? String(v) : '');
  return str;
};

const novaMut = { ...nova };
let rt  = '';
let nag = 'NOVA';
let nss = 'active';
// claudeAction: qué está haciendo NOVA — decide si Claude NLG aplica
// 'menu' → skip Claude (el menú debe ser exacto)
// 'handoff_sage' | 'handoff_atlas' → Claude personaliza la transición
// 'ask_city' | 'ask_specialty' → Claude hace la pregunta más natural
// 'fallback' → Claude intenta orientar mejor
// 'done' → skip Claude (confirmación estructurada)
let claudeAction = 'menu';

// ── PRIORIDAD 1: HANDOFFS ───────────────────────────────────
if (ph === 'SAGE') {
  novaMut.state = 'handoff_complete';
  return [{ json: {
    _handoffRequired: true,
    _handoffTo:       'SAGE',
    _handoffReason:   'cotizar_solicitado',
    _handoffFallback: t('handoff_sage'),   // fallback si handoff_manager falla
    userId:         parseInt(inp.userId),
    sessionId:      parseInt(inp.sessionId),
    userLanguage:   LANG,
    userName:       inp.userName || null,
    remoteJid:      inp.remoteJid,
    instance:       inp.instance,
    sessionContext: { ...ctx, nova: novaMut,
      sage:  { state: 'handoff_received', pendingMessage: inp.messageText },
      atlas: ctx.atlas || {}
    }
  }}];
} else if (ph === 'ATLAS') {
  novaMut.state = 'handoff_complete';
  return [{ json: {
    _handoffRequired: true,
    _handoffTo:       'ATLAS',
    _handoffReason:   'comparar_solicitado',
    _handoffFallback: t('handoff_atlas'),
    userId:         parseInt(inp.userId),
    sessionId:      parseInt(inp.sessionId),
    userLanguage:   LANG,
    userName:       inp.userName || null,
    remoteJid:      inp.remoteJid,
    instance:       inp.instance,
    sessionContext: { ...ctx, nova: novaMut,
      atlas: { state: 'handoff_received', pendingMessage: inp.messageText },
      sage:  ctx.sage || {}
    }
  }}];

// ── PRIORIDAD 2: AGENDAMIENTO ───────────────────────────────
} else if (state === 'gathering_appointment_city') {
  const isAffirmation = /^(s[íi]|si|yes|ok|dale|listo|claro|adelante|sure|sim|claro)$/i.test(txt);
  if (isAffirmation) {
    rt = t('ask_city');
    novaMut.state = 'gathering_appointment_city';
  } else {
    novaMut.appointment_city = inp.messageText;
    rt = t('city_received', { city: inp.messageText });
    novaMut.state = 'gathering_appointment_specialty';
  }
  claudeAction = 'ask_city';

} else if (state === 'gathering_appointment_specialty') {
  novaMut.appointment_specialty = inp.messageText;
  const city = novaMut.appointment_city || '—';
  rt  = t('appointment_done', { city, specialty: inp.messageText });
  novaMut.state = 'active';
  claudeAction = 'done'; // estructurado, no personalizar

} else if (intent.includes('agendar')) {
  rt = t('ask_city');
  novaMut.state = 'gathering_appointment_city';
  claudeAction = 'ask_city';

// ── PRIORIDAD 3: PRIMER CONTACTO ───────────────────────────
} else if (isNew) {
  rt = t('welcome');
  novaMut.state = 'initial_presented';
  claudeAction = 'menu'; // menú exacto, no personalizar

// ── PRIORIDAD 4: SALUDO ─────────────────────────────────────
} else if (intent === 'saludo' || intent === 'saludo_claude') {
  rt = t('saludo');
  novaMut.state = 'active';
  claudeAction = 'menu';

// ── FALLBACK ────────────────────────────────────────────────
} else {
  rt = t('fallback');
  novaMut.state = 'clarification_needed';
  claudeAction = 'fallback';
}

// Menús son hardcoded → skip Claude para velocidad y precisión
const claudeSkip = (claudeAction === 'menu' || claudeAction === 'done');

return [{ json: {
  success: true, responseText: rt, newActiveAgent: nag, newSessionState: nss,
  newSessionContext: { ...ctx, nova: novaMut },
  claudeAction, claudeSkip,
  claudeContext: { userMessage: inp.messageText, lang: LANG, userName: fn,
                   state: novaMut.state, intent },
  userId: parseInt(inp.userId), sessionId: parseInt(inp.sessionId),
  userLanguage: inp.userLanguage || 'es', detectedLanguage: LANG,
  userName: inp.userName || null, remoteJid: inp.remoteJid, instance: inp.instance
}}];

// Pass-through: el Motor ya construyó la respuesta completa.
// Este nodo existe para claridad visual en el canvas.
return [$input.first()];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'NOVA_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
  newActiveAgent: 'NOVA',
  _meta: { timestamp: new Date().toISOString(), source: 'nova_error' }
}}];

// ============================================================
// PREPARAR CLAUDE NLG NOVA v1.0
// Solo invocado cuando claudeSkip=false.
// Construye el prompt personalizado según la acción de NOVA.
// ============================================================
const motorOut = $input.first().json;

// Si claudeSkip=true → no debería llegar aquí (lo filtra el IF)
// pero por seguridad retornamos con flag
if (motorOut.claudeSkip) {
  return [{ json: { ...motorOut, _nlgSkip: true } }];
}

const { claudeAction, claudeContext, responseText } = motorOut;
const lang     = claudeContext?.lang || 'es';
const userName = claudeContext?.userName || null;
const userMsg  = claudeContext?.userMessage || '';
const nm       = userName ? ` ${userName}` : '';

const LANG_NAMES = { es: 'español', en: 'inglés', pt: 'portugués' };
const langName = LANG_NAMES[lang] || 'español';

// Instrucciones específicas por tipo de acción
const ACTION_PROMPTS = {
  handoff_sage: `El usuario quiere cotizar un procedimiento médico. Escribe un mensaje breve (máx 3 líneas) que:
1. Lo conecte con SAGE (especialista en cotizaciones de Pangi)
2. Mencione específicamente el procedimiento si puedes inferirlo del mensaje
3. Sea cálido e inspire confianza — es el inicio de la conversación
Tono: cálido, eficiente. NO hagas preguntas. NO digas que "ya tienes su información".`,

  handoff_atlas: `El usuario quiere comparar destinos médicos o calcular el costo total de un viaje. Escribe un mensaje breve (máx 3 líneas) que:
1. Lo conecte con ATLAS (consejero de turismo médico de Pangi)
2. Mencione que ATLAS calculará vuelo + alojamiento + procedimiento
3. Genere entusiasmo por explorar opciones
Tono: entusiasta, conciso. NO hagas preguntas.`,

  ask_city: `El usuario quiere agendar una cita médica. Escribe un mensaje breve (máx 2 líneas) que le pregunte naturalmente en qué ciudad necesita la cita. Tono: amigable y directo.`,

  fallback: `El usuario escribió algo que no está 100% claro. Escribe un mensaje breve (máx 3 líneas) que:
1. Muestre que entendiste parcialmente (si aplica)
2. Le ofrezca las 3 opciones de Pangi: cotizar, comparar destinos, agendar
3. Sea orientador, no confuso
Tono: paciente y servicial. USA emojis mínimos (💰🗺️🗓️).`
};

const actionPrompt = ACTION_PROMPTS[claudeAction] || ACTION_PROMPTS.fallback;

const systemPrompt = `Eres NOVA, la asistente de bienvenida de Pangi (plataforma de turismo médico latinoamericana).

REGLAS ABSOLUTAS:
- Responde SIEMPRE en ${langName}
- Usa el nombre del usuario si está disponible: "${userName || 'no disponible'}"
- Máximo 3-4 líneas de texto
- Formato WhatsApp: usa *negritas* con asteriscos para énfasis
- NO uses markdown como ##, **, etc.
- NO hagas preguntas en mensajes de handoff
- Genera SOLO el mensaje final, sin explicaciones

TAREA: ${actionPrompt}`;

return [{ json: {
  ...motorOut,
  _nlgSkip: false,
  claudeNlgPayload: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 200,
    system: systemPrompt,
    messages: [{ role: 'user', content: `El usuario escribió: "${userMsg}"` }]
  }
}}];

// ============================================================
// PROCESAR RESPUESTA NLG NOVA v1.0
// Merge: Claude NLG respuesta → responseText final.
// Fallback robusto: cualquier error → usa responseText del motor.
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — NLG NOVA').first().json;

// Si fue skip → pasar el motor output sin cambios
if (prepData._nlgSkip) {
  return [{ json: { ...prepData, _nlgSource: 'motor_skip' } }];
}

let finalText = prepData.responseText; // fallback siempre disponible

try {
  const claudeText = httpResult?.content?.[0]?.text;
  if (claudeText && claudeText.trim().length > 10) {
    finalText = claudeText.trim();
  }
} catch(e) {
  // Fallo silencioso → usa responseText del motor
}

return [{ json: {
  ...prepData,
  responseText: finalText,
  _nlgSource: finalText === prepData.responseText ? 'motor_fallback' : 'claude_nlg'
}}];

// ============================================================
// PREPARAR PAYLOAD HANDOFF v1.0
// Forma el input que espera 04_handoff_manager.
// ============================================================
const inp = $input.first().json;

return [{ json: {
  userId:          inp.userId,
  sessionId:       inp.sessionId,
  fromAgent:       'NOVA',
  toAgent:         inp._handoffTo,
  reason:          inp._handoffReason || 'intent_detected',
  userLanguage:    inp.userLanguage   || 'es',
  userName:        inp.userName       || null,
  contextSnapshot: inp.sessionContext || {}
}}];

// ============================================================
// MERGE HANDOFF RESULT v1.0
// Combina el resultado de 04_handoff_manager con el contexto de NOVA.
// Fallback robusto: si handoff_manager falla, usa el mensaje del motor.
// ============================================================
const hmResult  = $json;
const novaInput = $('🌟 NOVA — Validar + Motor').first().json;

// El handoff_manager devuelve 'handoffMessage'.
// Si falló (continueOnFail), usamos el _handoffFallback del motor.
const responseText = (hmResult?.success && hmResult?.handoffMessage && hmResult.handoffMessage.length > 5)
  ? hmResult.handoffMessage
  : (novaInput._handoffFallback || 'Conectando con el agente correspondiente...');

const dbSuccess = !!(hmResult?.success);
if (!dbSuccess) {
  console.warn('[PANGI] ⚠️ Handoff Manager falló — usando fallback de NOVA. Error:', hmResult?.error || 'desconocido');
}

return [{ json: {
  success:            true,
  responseText,
  newActiveAgent:     novaInput._handoffTo,
  newSessionState:    'handoff_received',
  newSessionContext: {
    ...novaInput.sessionContext,
    language: novaInput.userLanguage || 'es'
  },
  claudeSkip:         true,
  userId:             novaInput.userId,
  sessionId:          novaInput.sessionId,
  userLanguage:       novaInput.userLanguage || 'es',
  userName:           novaInput.userName     || null,
  remoteJid:          novaInput.remoteJid,
  instance:           novaInput.instance,
  _handoffDbLogged:   dbSuccess
}}];
